/// Creates a 16-by-16, theme-inheriting WinUI path icon.
#[must_use]
pub fn path(icon: FaIcon) -> PathIcon {
    PathIcon::new()
        .data(icon.data())
        .width(ICON_SIZE)
        .height(ICON_SIZE)
}

